using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using StudentMgmt.EnrollmentService.Entities;

namespace StudentMgmt.EnrollmentService.Persistence.Configurations;

public class StudentSnapshotConfiguration : IEntityTypeConfiguration<StudentSnapshot>
{
    public void Configure(EntityTypeBuilder<StudentSnapshot> builder)
    {
        builder.ToTable("StudentSnapshots");

        // Id is NOT auto-generated by the database here — it is deliberately set
        // by SnapshotSyncService to equal the StudentId carried on the Kafka
        // event, so this row's primary key literally is the owning service's id.
        builder.HasKey(s => s.Id);
        builder.Property(s => s.Id).ValueGeneratedNever();

        builder.Property(s => s.FullName).IsRequired().HasMaxLength(200);
        builder.Property(s => s.Email).IsRequired().HasMaxLength(256);

        builder.Property(s => s.CreatedBy).IsRequired().HasMaxLength(100);
        builder.Property(s => s.UpdatedBy).HasMaxLength(100);
        builder.Property(s => s.DeletedBy).HasMaxLength(100);

        builder.Property(s => s.RowVersion).IsConcurrencyToken();

        builder.HasIndex(s => s.Email);

        builder.HasQueryFilter(s => !s.IsDeleted);
    }
}
